'use client';
// Isolated controllable loader adapter; never a production route or authentication provider.
import {useCallback,useEffect,useRef,useState} from 'react';import ImagePreview from '../components/elements/image-preview';import type {ImageLoader,ImageLoadResult} from '../components/elements/image-loader';
export default function Page(){const [revision,setRevision]=useState(0),[mounted,setMounted]=useState(true),[requests,setRequests]=useState<{request:number;src:string;aborted:boolean}[]>([]),sequence=useRef(0),pending=useRef(new Map<number,(value:ImageLoadResult)=>void>());const load=useCallback<ImageLoader>((src,signal)=>new Promise(resolve=>{const request=++sequence.current;pending.current.set(request,resolve);setRequests(values=>[...values,{request,src,aborted:false}]);signal.addEventListener('abort',()=>setRequests(values=>values.map(value=>value.request===request?{...value,aborted:true}:value)),{once:true});}),[]);
 useEffect(()=>{const control=(event:Event)=>{const d=(event as CustomEvent).detail;if(d.kind==='resolve')pending.current.get(d.request)?.(d.result);if(d.kind==='replace')setRevision(value=>value+1);if(d.kind==='unmount')setMounted(false);if(d.kind==='remount')setMounted(true);if(d.kind==='ending')window.dispatchEvent(new Event('templux:session-ending'));};window.addEventListener('fixture:image',control);return()=>window.removeEventListener('fixture:image',control);},[]);
 const a={id:'a',alt:'Controlled synthetic A · '+ '合成长替代文字，保持完整可读。'.repeat(35),sources:[`/examples/image-a.svg?rev=${revision}&primary`,`/examples/image-a.svg?rev=${revision}&backup`]},b={id:'b',alt:'Controlled synthetic B',sources:['/examples/image-b.svg?primary','/examples/image-b.svg?backup']},c={id:'c',alt:'Controlled synthetic C',sources:['/examples/image-c.svg']};return <main><h1>Image lifecycle fixture</h1><output aria-label="image requests">{JSON.stringify(requests)}</output><output aria-label="image revision">{revision}</output>{mounted&&<ImagePreview image={a} gallery={{enabled:true,images:[a,b,c]}} settings={{zoomPan:true,maxScale:4}} load={load}/>}</main>;
}
